const $=id=>document.getElementById(id),dayOf=t=>new Date(t).toLocaleDateString('en-CA',{timeZone:'America/Manaus'});let data=null;
const today=dayOf(Date.now());$('end').value=today;$('start').value=dayOf(Date.now()-6*86400000);
const num=v=>v===null?'Sem dados':v.toLocaleString('pt-BR',{maximumFractionDigits:1});
function option(select,value,label=value){const el=document.createElement('option');el.value=value;el.textContent=label;select.append(el);}
function table(target,headers,rows){const t=document.createElement('table'),h=t.createTHead().insertRow();for(const label of headers){const th=document.createElement('th');th.scope='col';th.textContent=label;h.append(th);}for(const values of rows){const row=t.insertRow();for(const v of values)row.insertCell().textContent=v;}$(target).replaceChildren(t);}
function chart(target,points,unit){const container=$(target);container.replaceChildren();if(!points.some(p=>p.value!==null)){const p=document.createElement('p');p.className='history-empty';p.textContent='Ainda não há registros para esta seleção. Novas coletas construirão o histórico.';container.append(p);return;}
 const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.classList.add('history-chart');svg.setAttribute('viewBox','0 0 1000 290');svg.setAttribute('role','img');svg.setAttribute('aria-label','Evolução diária em '+unit+'. Valores detalhados na tabela abaixo.');const top=Math.max(1,...points.map(p=>p.value??0))*1.15,x=i=>65+i*895/Math.max(1,points.length-1),y=v=>240-v/top*205;
 function el(tag,attrs,text){const n=document.createElementNS(ns,tag);for(const [k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text)n.textContent=text;svg.append(n);return n;}
 for(let i=0;i<4;i++){const value=top*i/3;el('line',{x1:65,x2:970,y1:y(value),y2:y(value),stroke:'#dce6df'});el('text',{x:5,y:y(value)+4},num(value));}
 for(let i=0;i<points.length;i++){const p=points[i];if(i%Math.max(1,Math.ceil(points.length/7))===0||i===points.length-1)el('text',{x:x(i),y:270,'text-anchor':'middle'},p.day.slice(8)+'/'+p.day.slice(5,7));if(p.value===null)continue;if(i&&!p.ongoing&&points[i-1].value!==null)el('line',{x1:x(i-1),y1:y(points[i-1].value),x2:x(i),y2:y(p.value),stroke:'#187757','stroke-width':3});const dot=el('circle',{cx:x(i),cy:y(p.value),r:5,fill:p.ongoing?'#b77618':'#187757'});const title=document.createElementNS(ns,'title');title.textContent=p.day+': '+num(p.value)+' '+unit+(p.ongoing?' — dia em andamento':'');dot.append(title);}container.append(svg);
}
const hiddenSensors=new Set();
const colors=['#0072B2','#D55E00','#009E73','#8B4BA8','#946200','#00666B','#B33F62'];
function populateSensors(){const old=$('sensor').value;$('sensor').replaceChildren();const records=data.days.flatMap(d=>d.air).filter(r=>r.source==='PurpleAir'&&(!$('neighborhood').value||r.neighborhood===$('neighborhood').value));const sensors=new Map(records.map(r=>[r.sensor,r.name]));option($('sensor'),'all','Comparar sensores · todos os bairros da seleção');for(const [id,name]of sensors)option($('sensor'),id,name);option($('sensor'),'cams','CAMS · estimativa regional, não do bairro');if([...$('sensor').options].some(o=>o.value===old))$('sensor').value=old;render();}
function render(){if(!data)return;const sensor=$('sensor').value;$('comparisonControls').hidden=sensor!=='all';if(sensor==='all'){renderComparison();renderFire();return;}const points=data.days.map(d=>{const rows=d.air.filter(r=>r.sensor===sensor);return {day:d.day,value:rows.length?rows.reduce((n,r)=>n+r.pm25,0)/rows.length:null,rows};});const rows=points.flatMap(p=>p.rows);$('airTitle').textContent=$('sensor').selectedOptions[0]?.textContent??'Concentração de PM2,5';$('daysCount').textContent=points.filter(p=>p.rows.length).length+' / '+points.length;$('samples').textContent=rows.length;$('peak').textContent=rows.length?num(Math.max(...rows.map(r=>r.pm25))):'—';chart('airChart',points,'µg/m³');table('airTable',['Dia (Manaus)','Média das amostras','Mínimo','Máximo','Amostras'],points.map(p=>[p.day,num(p.value),p.rows.length?num(Math.min(...p.rows.map(r=>r.pm25))):'—',p.rows.length?num(Math.max(...p.rows.map(r=>r.pm25))):'—',p.rows.length]));renderFire();}
function renderComparison(){
 const neighborhood=$('neighborhood').value;
 const records=data.days.flatMap(d=>d.air).filter(r=>r.source==='PurpleAir');
 const ids=[...new Set(records.map(r=>r.sensor))].sort();
 const available=ids.filter(id=>records.some(r=>r.sensor===id&&(!neighborhood||r.neighborhood===neighborhood)));
 const series=available.map(id=>{const record=records.find(r=>r.sensor===id),index=ids.indexOf(id);return {id,name:record.name,neighborhood:record.neighborhood||'Bairro não informado',color:colors[index%colors.length],dash:index>=colors.length?'7 4':'',points:data.days.map(d=>{const rows=d.air.filter(r=>r.source==='PurpleAir'&&r.sensor===id&&(!neighborhood||r.neighborhood===neighborhood)&&Number.isFinite(r.pm25));return {day:d.day,rows,value:rows.length?rows.reduce((sum,r)=>sum+r.pm25,0)/rows.length:null};})};});
 const controls=$('comparisonControls');controls.replaceChildren();
 const legend=document.createElement('legend');legend.textContent='Sensores no gráfico — marque para exibir';controls.append(legend);
 for(const seriesItem of series){const label=document.createElement('label'),input=document.createElement('input'),swatch=document.createElement('span');input.type='checkbox';input.checked=!hiddenSensors.has(seriesItem.id);input.addEventListener('change',()=>{input.checked?hiddenSensors.delete(seriesItem.id):hiddenSensors.add(seriesItem.id);render();});swatch.className='sensor-swatch';swatch.style.borderTopColor=seriesItem.color;swatch.style.borderTopStyle=seriesItem.dash?'dashed':'solid';label.append(input,swatch,seriesItem.name+' · '+seriesItem.neighborhood);controls.append(label);}
 const selected=series.filter(s=>!hiddenSensors.has(s.id)),rows=selected.flatMap(s=>s.points.flatMap(p=>p.rows));
 $('airTitle').textContent=neighborhood?'Comparação de sensores · '+neighborhood:'Comparação dos sensores monitorados';
 $('daysCount').textContent=new Set(selected.flatMap(s=>s.points.filter(p=>p.rows.length).map(p=>p.day))).size+' / '+data.days.length;
 $('samples').textContent=rows.length;$('peak').textContent=rows.length?num(Math.max(...rows.map(r=>r.pm25))):'—';
 const container=$('airChart');container.replaceChildren();
 if(!rows.length){const empty=document.createElement('p');empty.className='history-empty';empty.textContent=series.length?'Selecione sensores com amostras para visualizar o gráfico.':'Sem amostras de sensores neste bairro e período.';container.append(empty);}
 else{
 const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.classList.add('history-chart');svg.setAttribute('viewBox','0 0 1000 290');svg.setAttribute('role','img');svg.setAttribute('aria-label','Comparação das médias diárias por sensor em microgramas por metro cúbico. Consulte os nomes e valores na tabela abaixo.');
 const top=Math.max(1,...selected.flatMap(s=>s.points.map(p=>p.value??0)))*1.15,x=i=>65+i*895/Math.max(1,data.days.length-1),y=v=>240-v/top*205;
 function el(tag,attrs,text){const n=document.createElementNS(ns,tag);for(const [k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text)n.textContent=text;svg.append(n);return n;}
 for(let i=0;i<4;i++){const value=top*i/3;el('line',{x1:65,x2:970,y1:y(value),y2:y(value),stroke:'#dce6df'});el('text',{x:5,y:y(value)+4},num(value));}
 data.days.forEach((d,i)=>{if(i%Math.max(1,Math.ceil(data.days.length/7))===0||i===data.days.length-1)el('text',{x:x(i),y:270,'text-anchor':'middle'},d.day.slice(8)+'/'+d.day.slice(5,7));});
 for(const s of selected)s.points.forEach((p,i)=>{if(p.value===null)return;const ongoing=p.day===dayOf(Date.now());if(i&&!ongoing&&s.points[i-1].value!==null)el('line',{x1:x(i-1),y1:y(s.points[i-1].value),x2:x(i),y2:y(p.value),stroke:s.color,'stroke-width':2,'stroke-dasharray':s.dash});const dot=el('circle',{cx:x(i),cy:y(p.value),r:4,fill:ongoing?'white':s.color,stroke:s.color,'stroke-width':2});const title=document.createElementNS(ns,'title');title.textContent=s.name+' · '+p.day+': '+num(p.value)+' µg/m³ · '+p.rows.length+' amostras'+(ongoing?' · dia em andamento':'');dot.append(title);});container.append(svg);
 }
 table('airTable',['Sensor','Bairro','Dia (Manaus)','Média das amostras','Mínimo','Máximo','Amostras'],selected.flatMap(s=>s.points.map(p=>[s.name,s.neighborhood,p.day,num(p.value),p.rows.length?num(Math.min(...p.rows.map(r=>r.pm25))):'—',p.rows.length?num(Math.max(...p.rows.map(r=>r.pm25))):'—',p.rows.length])));
}
function renderFire(){
 const municipality=$('municipality').value,nowDay=dayOf(Date.now());
 const points=data.days.map(d=>{const rows=d.fire.filter(r=>!municipality||r.municipality===municipality);const ongoing=d.day===nowDay;return {day:d.day,value:rows.length?rows.length:null,ongoing,coverage:ongoing?'Dia em andamento — dados parciais':d.fire.length||d.collections.some(c=>c.fireAvailable)?'Dia encerrado — cobertura parcial':'Sem coleta de fogo disponível',label:rows.length?num(rows.length):ongoing?'Ainda sem registros recebidos para hoje':'Sem registros nos arquivos disponíveis'};});
 chart('fireChart',points,'detecções registradas (cobertura parcial)');
 table('fireTable',['Dia (Manaus)','Detecções registradas','Cobertura'],points.map(p=>[p.day,p.label,p.coverage]));
 const fires=data.days.flatMap(d=>d.fire),selected=fires.filter(r=>!municipality||r.municipality===municipality);
 const latest=values=>values.filter(v=>Number.isFinite(Date.parse(v))).sort((a,b)=>Date.parse(a)-Date.parse(b)).at(-1);
 const format=t=>t?new Date(t).toLocaleString('pt-BR',{timeZone:'America/Manaus'})+' (Manaus)':'Não disponível neste período';
 const collected=latest(fires.map(r=>r.collectedAt)),detected=latest(selected.map(r=>r.time)),archived=latest(data.days.flatMap(d=>d.collections).map(c=>c.time));
 $('fireTiming').textContent='Última coleta com detecções arquivadas no período: '+format(collected)+'. Detecção mais recente na seleção: '+format(detected)+'. Última atualização do arquivo no período: '+format(archived)+'.';
}

async function load(){const query=new URLSearchParams({start:$('start').value,end:$('end').value});$('status').textContent='Consultando arquivos…';try{const r=await fetch('/api/history?'+query);const result=await r.json();if(!r.ok)throw Error(result.error||'Histórico indisponível.');data=result;$('neighborhood').replaceChildren();option($('neighborhood'),'','Todos os bairros monitorados');for(const name of [...new Set(data.days.flatMap(d=>d.air).map(r=>r.neighborhood).filter(Boolean))].sort())option($('neighborhood'),name);$('municipality').replaceChildren();option($('municipality'),'','Amazonas · todos os municípios');for(const name of [...new Set(['MANAUS',...data.days.flatMap(d=>d.fire).map(r=>r.municipality)])].sort())option($('municipality'),name);populateSensors();$('status').textContent='Período carregado. '+data.note;for(const type of ['air','fire'])$(type+'Download').href='/api/history?'+query+'&csv='+type;$('dailyDownloads').replaceChildren();for(const d of data.days.filter(d=>d.air.length||d.fire.length||d.collections.length)){const p=document.createElement('p');p.append(d.day+' ');for(const type of ['air','fire']){const a=document.createElement('a');a.textContent=type==='air'?'Ar CSV':'Fogo CSV';a.href='/api/history?'+new URLSearchParams({start:d.day,end:d.day,csv:type});p.append(a);}$('dailyDownloads').append(p);}}catch(e){$('status').textContent=e.message;}}
$('filters').addEventListener('submit',e=>{e.preventDefault();load();});$('neighborhood').addEventListener('change',populateSensors);$('sensor').addEventListener('change',render);$('municipality').addEventListener('change',renderFire);load();
